create extension if not exists pgcrypto;
create table if not exists flats(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,flat_number text not null,monthly_rent numeric(12,2) default 0,electricity_rate numeric(12,2) default 0,meter_number text,status text default 'vacant',created_at timestamptz default now(),unique(owner_id,flat_number));
create table if not exists tenants(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,flat_id uuid not null references flats(id),name text not null,mobile text not null,email text,move_in date,move_out date,whatsapp_opt_in boolean default false,status text default 'active',created_at timestamptz default now());
create table if not exists bills(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,flat_id uuid not null references flats(id),tenant_id uuid references tenants(id),month text not null,rent numeric(12,2) default 0,previous_reading numeric(12,2) default 0,current_reading numeric(12,2) default 0,units numeric(12,2) default 0,electricity numeric(12,2) default 0,previous_due numeric(12,2) default 0,advance_adjusted numeric(12,2) default 0,total_due numeric(12,2) default 0,status text default 'unpaid',created_at timestamptz default now(),unique(owner_id,flat_id,month));
create table if not exists payments(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,flat_id uuid not null references flats(id),tenant_id uuid references tenants(id),bill_id uuid references bills(id),amount numeric(12,2) not null,payment_date date default current_date,mode text default 'cash',reference text,notes text,created_at timestamptz default now());
create table if not exists whatsapp_logs(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,tenant_id uuid references tenants(id),template_name text,recipient text,status text,provider_response jsonb,created_at timestamptz default now());
create or replace function record_payment(p_owner_id uuid,p_flat_id uuid,p_tenant_id uuid,p_bill_id uuid,p_amount numeric,p_payment_date date,p_mode text,p_reference text,p_notes text) returns jsonb language plpgsql security definer as $$ declare pid uuid;due numeric;paid numeric;st text;begin insert into payments(owner_id,flat_id,tenant_id,bill_id,amount,payment_date,mode,reference,notes) values(p_owner_id,p_flat_id,p_tenant_id,p_bill_id,p_amount,p_payment_date,p_mode,p_reference,p_notes) returning id into pid;if p_bill_id is not null then select total_due into due from bills where id=p_bill_id and owner_id=p_owner_id;select coalesce(sum(amount),0) into paid from payments where bill_id=p_bill_id and owner_id=p_owner_id;st:=case when paid>=coalesce(due,0) then 'paid' when paid>0 then 'partial' else 'unpaid' end;update bills set status=st where id=p_bill_id and owner_id=p_owner_id;end if;return jsonb_build_object('payment_id',pid,'status',coalesce(st,'recorded'));end$$;
alter table flats enable row level security;alter table tenants enable row level security;alter table bills enable row level security;alter table payments enable row level security;alter table whatsapp_logs enable row level security;
create policy flats_owner on flats for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy tenants_owner on tenants for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy bills_owner on bills for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy payments_owner on payments for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy whatsapp_owner on whatsapp_logs for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
